<div class="p-space-md bg-surface-container-low rounded-xl flex items-start gap-space-md">
<div class="w-10 h-10 rounded-full bg-surface-container-high text-primary flex-shrink-0 flex items-center justify-center">
<span class="material-symbols-outlined text-2xl">shield</span>
</div>
