</div>
</div>
<!-- Password Input with Toggle -->
<div class="flex flex-col gap-1.5">
<div class="flex items-center justify-between">
<label class="font-label-md text-label-md text-on-surface font-semibold" for="admin-password">Admin Password</label>
<a class="font-label-sm text-label-sm text-primary hover:underline font-semibold" href="{{ route('admin.login') }}?reset=1">Forgot Password?</a>
</div>
<div class="relative flex items-center">
