<button aria-label="Toggle password visibility" class="absolute right-3 p-1.5 text-on-surface-variant hover:text-on-surface rounded-full transition-colors flex items-center justify-center" id="toggle-password-btn" onclick="togglePasswordVisibility()" type="button">
<span class="material-symbols-outlined text-xl" id="toggle-icon">visibility</span>
</button>
