<script>
  function togglePasswordVisibility() {
    var passwordInput = document.getElementById('admin-password');
    var toggleIcon = document.getElementById('toggle-icon');
    if (!passwordInput || !toggleIcon) return;
    
    if (passwordInput.type === 'password') {
      passwordInput.type = 'text';
      toggleIcon.textContent = 'visibility_off';
    } else {
      passwordInput.type = 'password';
      toggleIcon.textContent = 'visibility';
    }
  }

  function handleAdminAuth() {
    var btn = document.getElementById('submit-login-btn');
    if (!btn) return;
    
    btn.innerHTML = '<span class="material-symbols-outlined animate-spin text-xl">sync</span><span>Verifying Geofence Keys...</span>';
    btn.disabled = true;
    
    setTimeout(function() {
      btn.innerHTML = '<span class="material-symbols-outlined text-xl">task_alt</span><span>Credentials Authorized</span>';
      setTimeout(function() {
        window.location.href = "{{ route('admin') }}";
      }, 1800);
    }, 1000);
  }
</script></main><footer class="w-full py-space-md flex flex-wrap items-center justify-center gap-space-lg text-on-surface-variant font-label-sm text-label-sm"><div class="flex items-center gap-space-xs"><span class="material-symbols-outlined text-sm text-tertiary">lock</span><span>256-Bit TLS End-to-End Encryption</span></div><div class="flex items-center gap-space-xs"><span class="material-symbols-outlined text-sm text-tertiary">verified_user</span><span>SOC2 Type II Certified</span></div><div class="flex items-center gap-space-xs"><span class="material-symbols-outlined text-sm text-tertiary">pin_drop</span><span>Anti-Spoof Geofence Verification</span></div></footer></body></html>
